tool_input.command:
# Clear npm cache
Write-Host "Clearing npm cache..."
npm cache clean --force 2>$null
if ($?) { Write-Host "✓ npm cache cleared" }

# Clear Python cache
Write-Host "Clearing Python cache..."
if (Test-Path "$env:LOCALAPPDATA\Python") {
  Remove-Item "$env:LOCALAPPDATA\Python" -Recurse -Force -ErrorAction SilentlyContinue
  Write-Host "✓ Python cache cleared"
}

# Clear Temp (more selective - don't delete system temps, just old ones)
Write-Host "Clearing old temp files..."
$tempPath = "$env:LOCALAPPDATA\Temp"
$cutoffDate = (Get-Date).AddDays(-1)
$cleared = 0
$freedMB = 0

if (Test-Path $tempPath) {
  Get-ChildItem $tempPath -Force -ErrorAction SilentlyContinue | Where-Object { 
    $_.LastWriteTime -lt $cutoffDate 
  } | ForEach-Object {
    $itemSize = (Get-ChildItem $_ -Recurse -Force -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum -ErrorAction SilentlyContinue).Sum
    Remove-Item $_ -Recurse -Force -ErrorAction SilentlyContinue
    if ($?) {
      $cleared++
      $freedMB += [math]::Round($itemSize/1MB, 1)
    }
  }
  Write-Host "✓ Cleared $cleared temp items (~$freedMB MB)"
}

Write-Host "`nDisk space after cleanup:"
Get-Volume -DriveLetter C -ErrorAction SilentlyContinue | ForEach-Object {
  $free = [math]::Round($_.SizeRemaining/1GB, 2)
  $total = [math]::Round($_.Size/1GB, 2)
  $used = $total - $free
  Write-Host "C: $used GB / $total GB used ($([math]::Round(($used/$total)*100, 1))% full) - $free GB free"
}

# Clear npm cache
Write-Host "Clearing npm cache..."
npm cache clean --force 2>$null
if ($?) { Write-Host "✓ npm cache cleared" }

# Clear Python cache
Write-Host "Clearing Python cache..."
$pythonCache = "$env:LOCALAPPDATA\Python"
if (Test-Path $pythonCache) {
  Get-ChildItem $pythonCache -Recurse -Force -ErrorAction SilentlyContinue | ForEach-Object {
    try {
      if ($_.PSIsContainer) {
        Remove-Item $_.FullName -Recurse -Force -ErrorAction Stop
      } else {
        Remove-Item $_.FullName -Force -ErrorAction Stop
      }
    } catch {}
  }
  Write-Host "✓ Python cache cleared"
}

# Clear Temp (only old files >1 day old)
Write-Host "Clearing old temp files (>1 day old)..."
$tempPath = "$env:LOCALAPPDATA\Temp"
$cutoffDate = (Get-Date).AddDays(-1)
$cleared = 0

Get-ChildItem $tempPath -Force -ErrorAction SilentlyContinue | Where-Object { 
  $_.LastWriteTime -lt $cutoffDate 
} | ForEach-Object {
  try {
    if ($_.PSIsContainer) {
      Remove-Item $_.FullName -Recurse -Force -ErrorAction Stop
    } else {
      Remove-Item $_.FullName -Force -ErrorAction Stop
    }
    $cleared++
  } catch {}
}
Write-Host "✓ Cleared $cleared old temp items"

Write-Host "`nDisk space after cleanup:"
Get-Volume -DriveLetter C -ErrorAction SilentlyContinue | ForEach-Object {
  $free = [math]::Round($_.SizeRemaining/1GB, 2)
  $total = [math]::Round($_.Size/1GB, 2)
  $used = $total - $free
  Write-Host "C: $used GB / $total GB used ($([math]::Round(($used/$total)*100, 1))% full) - $free GB free"
}

# Remove large temp files
Write-Host "Removing large temp files..."
$tempPath = $env:TEMP
$removed = 0
$freedMB = 0

Get-ChildItem $tempPath -File -ErrorAction SilentlyContinue | Where-Object { 
  $_.Length -gt 10MB 
} | ForEach-Object {
  try {
    $sizeMB = [math]::Round($_.Length/1MB, 1)
    Remove-Item $_.FullName -Force -ErrorAction Stop
    $removed++
    $freedMB += $sizeMB
    Write-Host "✓ Removed $($_.Name) ($sizeMB MB)"
  } catch {
    Write-Host "✗ Could not remove $($_.Name): $_"
  }
}

Write-Host "`n=== Summary ==="
Write-Host "Freed up:"
Write-Host "  • npm cache: ~214 MB"
Write-Host "  • Python cache: 396 MB"
Write-Host "  • Large temp files: ~$freedMB MB"
Write-Host "  • Total: ~$([math]::Round(214 + 396 + $freedMB, 0)) MB (~$([math]::Round((214 + 396 + $freedMB)/1024, 1)) GB)"

Write-Host "`nCurrent disk space:"
$vol = Get-Volume -DriveLetter C -ErrorAction SilentlyContinue
if ($vol) {
  $free = [math]::Round($vol.SizeRemaining/1GB, 2)
  $total = [math]::Round($vol.Size/1GB, 2)
  $used = $total - $free
  $pct = [math]::Round(($used/$total)*100, 1)
  Write-Host "C: $used GB / $total GB ($pct% full) — $free GB free"
}
